import type {PushInput} from "../types/push-input.js";
import {commonEvent,mapEvent,troopEvent,showPicture,imageAsset,callCommonEvent,commonEventRef,forceAction,actorRef,skillRef,showAnimation,animationRef} from "rpgmaker-event-dsl";
export const event=commonEvent({id:10,name:"Push workflow",trigger:"none",commands:[showPicture({pictureId:1,image:imageAsset({folder:"pictures",name:"PushPoster"}),origin:"upperLeft",position:{kind:"direct",x:0,y:0},scaleX:100,scaleY:100,opacity:255,blendMode:"normal"})]});
import {switchDefinition} from "rpgmaker-event-dsl";
export const gate=switchDefinition({id:1,name:"Recovery switch"});

before.publicTypes:
//#region src/domain/references.d.ts
type ReferenceKind = "actor" | "animation" | "armor" | "class" | "commonEvent" | "enemy" | "item" | "map" | "skill" | "state" | "switch" | "tileset" | "troop" | "variable" | "weapon";
declare const audioAssetFolders: readonly ["bgm", "bgs", "me", "se"];
declare const imageAssetFolders: readonly ["animations", "battlebacks1", "battlebacks2", "characters", "enemies", "faces", "parallaxes", "pictures", "sv_actors", "sv_enemies", "system", "tilesets", "titles1", "titles2"];
type ReferenceValue<TKind extends ReferenceKind> = {
  id: number;
  kind: TKind;
} | {
  kind: TKind;
  name: string;
};
type AudioAssetFolder = (typeof audioAssetFolders)[number];
type ImageAssetFolder = (typeof imageAssetFolders)[number];
type AudioAssetReference<Folder extends AudioAssetFolder = AudioAssetFolder> = {
  kind: "asset";
  category: "audio";
  folder: Folder;
  name: string;
};
type ImageAssetReference = {
  kind: "asset";
  category: "image";
  folder: ImageAssetFolder;
  name: string;
};
type MovieAssetReference = {
  kind: "asset";
  category: "movie";
  folder: "movies";
  name: string;
};
type AssetReference = AudioAssetReference | ImageAssetReference | MovieAssetReference;
type RuntimeSelector<TScope extends string = string, TTarget extends string = string> = {
  kind: "runtimeSelector";
  scope: TScope;
  target: TTarget;
};
type ScriptInput = {
  kind: "scriptInput";
  code: string;
};
type ReferenceRange<TKind extends ReferenceKind> = {
  kind: "referenceRange";
  from: ReferenceValue<TKind>;
  to: ReferenceValue<TKind>;
};
type NumericRange = {
  kind: "numericRange";
  from: number;
  to: number;
};
type ConstantOperand = {
  kind: "constant";
  value: number;
};
type VariableOperand = {
  kind: "variable";
  variable: ReferenceValue<"variable">;
};
type RandomOperand = {
  kind: "random";
  from: number;
  to: number;
};
type ScriptOperand = {
  kind: "script";
  script: ScriptInput;
};
type ControlVariablesGameDataOperand = {
  kind: "gameData";
  source: "item";
  item: ReferenceValue<"item">;
} | {
  kind: "gameData";
  source: "weapon";
  weapon: ReferenceValue<"weapon">;
} | {
  kind: "gameData";
  source: "armor";
  armor: ReferenceValue<"armor">;
} | {
  kind: "gameData";
  source: "actor";
  actor: ReferenceValue<"actor">;
  value: "level" | "exp" | "hp" | "mp" | "mhp" | "mmp" | "atk" | "def" | "mat" | "mdf" | "agi" | "luk";
} | {
  kind: "gameData";
  source: "enemy";
  enemy: RuntimeSelector<"enemy", "enemy"> & {
    index: number;
  };
  value: "hp" | "mp" | "mhp" | "mmp" | "atk" | "def" | "mat" | "mdf" | "agi" | "luk";
} | {
  kind: "gameData";
  source: "character";
  target: CharacterRuntimeSelector;
  value: "mapX" | "mapY" | "direction" | "screenX" | "screenY";
} | {
  kind: "gameData";
  source: "party";
  member: RuntimeSelector<"party", "member"> & {
    index: number;
  };
} | {
  kind: "gameData";
  source: "other";
  value: "mapId" | "partyMembers" | "gold" | "steps" | "playTime" | "timer" | "saveCount" | "battleCount" | "winCount" | "escapeCount";
};
type CommandOperand = ConstantOperand | VariableOperand | RandomOperand | ControlVariablesGameDataOperand | ScriptOperand;
type OperateValueOperand = number | ReferenceValue<"variable">;
type OperateValueInput = {
  operation: "increase" | "decrease";
  operand: OperateValueOperand;
};
type ActorResourceTarget = RuntimeSelector<"actor", "entireParty"> | (RuntimeSelector<"actor", "actor"> & {
  actor: ReferenceValue<"actor">;
}) | (RuntimeSelector<"actor", "actorFromVariable"> & {
  variable: ReferenceValue<"variable">;
});
type ActorResourceOperand = ConstantOperand | VariableOperand;
type EquipmentRuntimeSelector = RuntimeSelector<"equipment", "idForSlot"> & {
  id: number;
};
type EnemyCommandTarget = (RuntimeSelector<"enemy", "all"> & {
  index?: never;
}) | (RuntimeSelector<"enemy", "enemy"> & {
  index: number;
});
type BattlerCommandTarget = (RuntimeSelector<"battler", "enemy"> & {
  index: number;
  actorId?: never;
}) | (RuntimeSelector<"battler", "actor"> & {
  actor: ReferenceValue<"actor">;
  index?: never;
});
type ActorParameter = "mhp" | "mmp" | "atk" | "def" | "mat" | "mdf" | "agi" | "luk";
type DirectPosition = {
  kind: "direct";
  x: number;
  y: number;
};
type VariablePosition = {
  kind: "variables";
  x: ReferenceValue<"variable">;
  y: ReferenceValue<"variable">;
};
type CommandPosition = DirectPosition | VariablePosition;
type VehicleTarget = "boat" | "ship" | "airship";
type Direction = 2 | 4 | 6 | 8;
type LocationDirection = "retain" | "down" | "left" | "right" | "up";
type TransferFade = "black" | "white" | "none";
type CharacterRuntimeSelector = (RuntimeSelector<"character", "player"> & {
  id?: never;
}) | (RuntimeSelector<"character", "currentEvent"> & {
  id?: never;
}) | (RuntimeSelector<"character", "event"> & {
  id: number;
});
type EventRuntimeSelector = Exclude<CharacterRuntimeSelector, {
  target: "player";
}>;
type DirectMapDestination = {
  kind: "direct";
  map: ReferenceValue<"map">;
  x: number;
  y: number;
};
type VariableMapDestination = {
  kind: "variables";
  map: ReferenceValue<"variable">;
  x: ReferenceValue<"variable">;
  y: ReferenceValue<"variable">;
};
type MapDestination = DirectMapDestination | VariableMapDestination;
type DirectEventLocationDestination = {
  kind: "direct";
  x: number;
  y: number;
};
type VariableEventLocationDestination = {
  kind: "variables";
  x: ReferenceValue<"variable">;
  y: ReferenceValue<"variable">;
};
type ExchangeEventLocationDestination = {
  kind: "exchange";
  target: EventRuntimeSelector;
};
type EventLocationDestination = DirectEventLocationDestination | VariableEventLocationDestination | ExchangeEventLocationDestination;
type ToneInput = {
  red: number;
  green: number;
  blue: number;
  gray: number;
};
type ColorInput = {
  red: number;
  green: number;
  blue: number;
  alpha: number;
};
type AudioPayload<Folder extends AudioAssetFolder = AudioAssetFolder> = {
  asset: AudioAssetReference<Folder> | null;
  volume: number;
  pitch: number;
  pan: number;
};
type LocationInfoType = "terrainTag" | "eventId" | "tileLayer1" | "tileLayer2" | "tileLayer3" | "tileLayer4" | "regionId";
type ConditionalVariableOperator = "eq" | "ge" | "le" | "gt" | "lt" | "ne";
type ConditionalBranchCondition = {
  kind: "switch";
  switch: ReferenceValue<"switch">;
  value: boolean;
} | {
  kind: "variable";
  variable: ReferenceValue<"variable">;
  operator: ConditionalVariableOperator;
  value: ConstantOperand | VariableOperand;
} | {
  kind: "selfSwitch";
  selfSwitch: "A" | "B" | "C" | "D";
  value: boolean;
} | {
  kind: "timer";
  seconds: number;
  operator: "ge" | "le";
} | {
  kind: "actor";
  actor: ReferenceValue<"actor">;
  check: {
    kind: "inParty";
  } | {
    kind: "name";
    name: string;
  } | {
    kind: "class";
    class: ReferenceValue<"class">;
  } | {
    kind: "skill";
    skill: ReferenceValue<"skill">;
  } | {
    kind: "weapon";
    weapon: ReferenceValue<"weapon">;
  } | {
    kind: "armor";
    armor: ReferenceValue<"armor">;
  } | {
    kind: "state";
    state: ReferenceValue<"state">;
  };
} | {
  kind: "enemy";
  enemy: Extract<EnemyCommandTarget, {
    target: "enemy";
  }>;
  check: {
    kind: "appeared";
  } | {
    kind: "state";
    state: ReferenceValue<"state">;
  };
} | {
  kind: "character";
  target: CharacterRuntimeSelector;
  direction: 2 | 4 | 6 | 8;
} | {
  kind: "gold";
  amount: number;
  operator: "ge" | "le" | "lt";
} | {
  kind: "item";
  item: ReferenceValue<"item">;
} | {
  kind: "weapon";
  weapon: ReferenceValue<"weapon">;
  includeEquipment: boolean;
} | {
  kind: "armor";
  armor: ReferenceValue<"armor">;
  includeEquipment: boolean;
} | {
  kind: "button";
  button: "ok" | "cancel" | "shift" | "down" | "left" | "right" | "up" | "pageup" | "pagedown";
} | {
  kind: "script";
  script: ScriptInput;
} | {
  kind: "vehicle";
  vehicle: "boat" | "ship" | "airship";
};
declare function isProjectDataReference(value: unknown): value is ReferenceValue<ReferenceKind>;
declare function isAssetReference(value: unknown): value is AssetReference;
declare function isRuntimeSelector(value: unknown): value is RuntimeSelector;
declare function isScriptInput(value: unknown): value is ScriptInput;
//#endregion
//#region src/domain/command.d.ts
type DslCommand = ShowTextDslCommand | InputNumberDslCommand | SelectItemDslCommand | ShowScrollingTextDslCommand | ConditionalDslCommand | LoopDslCommand | BreakLoopDslCommand | ExitEventProcessingDslCommand | CommonEventDslCommand | LabelDslCommand | JumpToLabelDslCommand | CommentDslCommand | ScriptDslCommand | PluginDslCommand | TransferPlayerDslCommand | ControlSwitchesDslCommand | ControlVariablesDslCommand | ControlSelfSwitchDslCommand | ControlTimerDslCommand | ChangeGoldDslCommand | ChangeItemsDslCommand | ChangeWeaponsDslCommand | ChangeArmorsDslCommand | ChangePartyMemberDslCommand | ChangeBattleBgmDslCommand | ChangeVictoryMeDslCommand | ChangeSaveAccessDslCommand | ChangeMenuAccessDslCommand | ChangeEncounterDslCommand | ChangeFormationAccessDslCommand | ChangeWindowColorDslCommand | ChangeDefeatMeDslCommand | ChangeVehicleBgmDslCommand | SetVehicleLocationDslCommand | SetEventLocationDslCommand | ScrollMapDslCommand | SetMovementRouteDslCommand | GetOnOffVehicleDslCommand | ChangeTransparencyDslCommand | ShowAnimationDslCommand | ShowBalloonIconDslCommand | ChangePlayerFollowersDslCommand | GatherFollowersDslCommand | FadeoutScreenDslCommand | FadeinScreenDslCommand | TintScreenDslCommand | FlashScreenDslCommand | ShakeScreenDslCommand | WaitDslCommand | ShowPictureDslCommand | MovePictureDslCommand | RotatePictureDslCommand | TintPictureDslCommand | ErasePictureDslCommand | SetWeatherEffectDslCommand | PlayBgmDslCommand | FadeoutBgmDslCommand | SaveBgmDslCommand | ReplayBgmDslCommand | PlayBgsDslCommand | FadeoutBgsDslCommand | PlayMeDslCommand | PlaySeDslCommand | StopSeDslCommand | PlayMovieDslCommand | ChangeMapNameDisplayDslCommand | ChangeTilesetDslCommand | ChangeBattleBackDslCommand | ChangeParallaxDslCommand | GetLocationInfoDslCommand | EraseEventDslCommand | BattleProcessingDslCommand | ShowChoicesDslCommand | ShopProcessingDslCommand | NameInputProcessingDslCommand | ChangeHpDslCommand | ChangeMpDslCommand | ChangeStateDslCommand | RecoverAllDslCommand | ChangeExpDslCommand | ChangeLevelDslCommand | ChangeParameterDslCommand | ChangeSkillDslCommand | ChangeEquipmentDslCommand | ChangeNameDslCommand | ChangeClassDslCommand | ChangeActorImagesDslCommand | ChangeVehicleImageDslCommand | ChangeNicknameDslCommand | ChangeProfileDslCommand | ChangeTpDslCommand | ChangeEnemyHpDslCommand | ChangeEnemyMpDslCommand | ChangeEnemyStateDslCommand | EnemyRecoverAllDslCommand | EnemyAppearDslCommand | EnemyTransformDslCommand | ShowBattleAnimationDslCommand | ForceActionDslCommand | AbortBattleDslCommand | ChangeEnemyTpDslCommand | OpenMenuScreenDslCommand | OpenSaveScreenDslCommand | GameOverDslCommand | ReturnToTitleScreenDslCommand | RawDslCommand;
type ShowTextDslCommand = {
  kind: "showText";
  lines: readonly [string, ...string[]];
  face: {
    image: ImageAssetReference | null;
    index: number;
  };
  background: "window" | "dim" | "transparent";
  position: "top" | "middle" | "bottom";
};
type InputNumberDslCommand = {
  kind: "inputNumber";
  variable: ReferenceValue<"variable">;
  digits: number;
};
type SelectItemDslCommand = {
  kind: "selectItem";
  variable: ReferenceValue<"variable">;
  itemType: "regular" | "key" | "hiddenA" | "hiddenB";
};
type ShowScrollingTextDslCommand = {
  kind: "showScrollingText";
  lines: readonly [string, ...string[]];
  speed: number;
  noFastForward: boolean;
};
type ShowChoicesDslCommand = {
  kind: "showChoices";
  choices: readonly [ChildCommandBody & {
    text: string;
  }, ...(ChildCommandBody & {
    text: string;
  })[]];
  defaultChoice?: {
    kind: "none";
  } | {
    kind: "choice";
    index: number;
  };
  cancel?: {
    kind: "disabled";
  } | {
    kind: "choice";
    index: number;
  } | (ChildCommandBody & {
    kind: "branch";
  });
  position?: "left" | "center" | "right";
  background?: "window" | "dim" | "transparent";
};
type ConditionalDslCommand = {
  kind: "conditional";
  condition: ConditionalBranchCondition;
  then: ChildCommandBody;
  else?: ChildCommandBody;
};
type ChildCommandBody = {
  commands: readonly DslCommand[];
  endMarker?: "present" | "absent";
};
type LoopDslCommand = {
  kind: "loop";
  body: ChildCommandBody;
};
type BreakLoopDslCommand = {
  kind: "breakLoop";
};
type ExitEventProcessingDslCommand = {
  kind: "exitEventProcessing";
};
type CommonEventDslCommand = {
  kind: "commonEvent";
  commonEvent: ReferenceValue<"commonEvent">;
};
type LabelDslCommand = {
  kind: "label";
  name: string;
};
type JumpToLabelDslCommand = {
  kind: "jumpToLabel";
  name: string;
};
type CommentDslCommand = {
  kind: "comment";
  lines: readonly [string, ...string[]];
};
type ScriptDslCommand = {
  kind: "script";
  script: ScriptInput;
};
type PluginDslCommand = {
  kind: "pluginCommand";
  line: string;
};
type TransferPlayerDslCommand = {
  kind: "transferPlayer";
  destination: MapDestination;
  direction?: LocationDirection;
  fade?: TransferFade;
};
type ControlSwitchesDslCommand = {
  kind: "controlSwitches";
  switch: ReferenceValue<"switch"> | ReferenceRange<"switch">;
  value: boolean;
};
type ControlVariablesDslCommand = {
  kind: "controlVariables";
  variable: ReferenceValue<"variable"> | ReferenceRange<"variable">;
  operation: "set" | "add" | "sub" | "mul" | "div" | "mod";
  value: CommandOperand;
};
type ControlSelfSwitchDslCommand = {
  kind: "controlSelfSwitch";
  selfSwitch: "A" | "B" | "C" | "D";
  value: boolean;
};
type ControlTimerDslCommand = {
  kind: "controlTimer";
  action: "start";
  seconds: number;
} | {
  kind: "controlTimer";
  action: "stop";
  seconds?: number;
};
type ChangeGoldDslCommand = {
  kind: "changeGold";
  operation: "gain" | "lose";
  value: ConstantOperand | VariableOperand;
};
type ChangeItemsDslCommand = {
  kind: "changeItems";
  item: ReferenceValue<"item">;
  operation: "gain" | "lose";
  amount: ConstantOperand | VariableOperand;
};
type ChangeWeaponsDslCommand = {
  kind: "changeWeapons";
  weapon: ReferenceValue<"weapon">;
  operation: "gain" | "lose";
  amount: ConstantOperand | VariableOperand;
  includeEquipment: boolean;
};
type ChangeArmorsDslCommand = {
  kind: "changeArmors";
  armor: ReferenceValue<"armor">;
  operation: "gain" | "lose";
  amount: ConstantOperand | VariableOperand;
  includeEquipment: boolean;
};
type ChangePartyMemberDslCommand = {
  kind: "changePartyMember";
  actor: ReferenceValue<"actor">;
  operation: "add" | "remove";
  initialize: boolean;
};
type ChangeBattleBgmDslCommand = {
  kind: "changeBattleBgm";
  audio: AudioPayload<"bgm">;
};
type ChangeVictoryMeDslCommand = {
  kind: "changeVictoryMe";
  audio: AudioPayload<"me">;
};
type ChangeSaveAccessDslCommand = {
  kind: "changeSaveAccess";
  enabled: boolean;
};
type ChangeMenuAccessDslCommand = {
  kind: "changeMenuAccess";
  enabled: boolean;
};
type ChangeEncounterDslCommand = {
  kind: "changeEncounter";
  enabled: boolean;
};
type ChangeFormationAccessDslCommand = {
  kind: "changeFormationAccess";
  enabled: boolean;
};
type ChangeWindowColorDslCommand = {
  kind: "changeWindowColor";
  tone: ToneInput;
};
type ChangeDefeatMeDslCommand = {
  kind: "changeDefeatMe";
  audio: AudioPayload<"me">;
};
type ChangeVehicleBgmDslCommand = {
  kind: "changeVehicleBgm";
  vehicle: VehicleTarget;
  audio: AudioPayload<"bgm">;
};
type SetVehicleLocationDslCommand = {
  kind: "setVehicleLocation";
  vehicle: VehicleTarget;
  destination: MapDestination;
};
type SetEventLocationDslCommand = {
  kind: "setEventLocation";
  target: EventRuntimeSelector;
  destination: EventLocationDestination;
  direction?: LocationDirection;
};
type ScrollMapDslCommand = {
  kind: "scrollMap";
  direction: "down" | "left" | "right" | "up";
  distance: number;
  speed: number;
};
type MoveRouteCommand = MoveRouteInstruction & {
  savedShape?: {
    indent?: "absent" | "null" | "zero";
  };
};
type MovementRoute = {
  commands: readonly MoveRouteCommand[];
  repeat?: boolean;
  skippable?: boolean;
  wait?: boolean;
  terminator?: {
    parameters?: "absent" | "empty";
  };
};
type MoveRouteInstruction = {
  kind: "moveDown";
} | {
  kind: "moveLeft";
} | {
  kind: "moveRight";
} | {
  kind: "moveUp";
} | {
  kind: "moveLowerLeft";
} | {
  kind: "moveLowerRight";
} | {
  kind: "moveUpperLeft";
} | {
  kind: "moveUpperRight";
} | {
  kind: "moveRandom";
} | {
  kind: "moveTowardPlayer";
} | {
  kind: "moveAwayFromPlayer";
} | {
  kind: "moveForward";
} | {
  kind: "moveBackward";
} | {
  kind: "jump";
  x: number;
  y: number;
} | {
  kind: "wait";
  frames: number;
} | {
  kind: "turnDown";
} | {
  kind: "turnLeft";
} | {
  kind: "turnRight";
} | {
  kind: "turnUp";
} | {
  kind: "turn90Right";
} | {
  kind: "turn90Left";
} | {
  kind: "turn180";
} | {
  kind: "turn90RightOrLeft";
} | {
  kind: "turnRandom";
} | {
  kind: "turnTowardPlayer";
} | {
  kind: "turnAwayFromPlayer";
} | {
  kind: "switchOn";
  switch: ReferenceValue<"switch">;
} | {
  kind: "switchOff";
  switch: ReferenceValue<"switch">;
} | {
  kind: "changeSpeed";
  speed: number;
} | {
  kind: "changeFrequency";
  frequency: number;
} | {
  kind: "walkAnimation";
  enabled: boolean;
} | {
  kind: "stepAnimation";
  enabled: boolean;
} | {
  kind: "directionFix";
  enabled: boolean;
} | {
  kind: "through";
  enabled: boolean;
} | {
  kind: "transparent";
  enabled: boolean;
} | {
  kind: "changeImage";
  character: ImageAssetReference | null;
  characterIndex: number;
} | {
  kind: "changeOpacity";
  opacity: number;
} | {
  kind: "changeBlendMode";
  blendMode: "normal" | "additive" | "multiply" | "screen";
} | {
  kind: "playSe";
  audio: {
    asset: AudioAssetReference | null;
    volume: number;
    pitch: number;
    pan: number;
  };
} | {
  kind: "script";
  script: ScriptInput;
};
type SetMovementRouteDslCommand = {
  kind: "setMovementRoute";
  target: CharacterRuntimeSelector;
  route: MovementRoute;
};
type GetOnOffVehicleDslCommand = {
  kind: "getOnOffVehicle";
};
type ChangeTransparencyDslCommand = {
  kind: "changeTransparency";
  transparent: boolean;
};
type ShowAnimationDslCommand = {
  kind: "showAnimation";
  target: CharacterRuntimeSelector;
  animation: ReferenceValue<"animation">;
  wait: boolean;
};
type BalloonIcon = "exclamation" | "question" | "musicNote" | "heart" | "anger" | "sweat" | "cobweb" | "silence" | "lightBulb" | "zzz" | "userDefined1" | "userDefined2" | "userDefined3" | "userDefined4" | "userDefined5";
type ShowBalloonIconDslCommand = {
  kind: "showBalloonIcon";
  target: CharacterRuntimeSelector;
  balloon: BalloonIcon;
  wait: boolean;
};
type ChangePlayerFollowersDslCommand = {
  kind: "changePlayerFollowers";
  visible: boolean;
};
type GatherFollowersDslCommand = {
  kind: "gatherFollowers";
};
type FadeoutScreenDslCommand = {
  kind: "fadeoutScreen";
};
type FadeinScreenDslCommand = {
  kind: "fadeinScreen";
};
type TintScreenDslCommand = {
  kind: "tintScreen";
  tone: ToneInput;
  duration: number;
  wait: boolean;
};
type FlashScreenDslCommand = {
  kind: "flashScreen";
  color: ColorInput;
  duration: number;
  wait: boolean;
};
type ShakeScreenDslCommand = {
  kind: "shakeScreen";
  power: number;
  speed: number;
  duration: number;
  wait: boolean;
};
type WaitDslCommand = {
  kind: "wait";
  frames: number;
};
type PictureOrigin = "upperLeft" | "center";
type PicturePosition = CommandPosition;
type PictureDisplayInput = {
  origin: PictureOrigin;
  scaleX: number;
  scaleY: number;
  opacity: number;
  blendMode: "normal" | "additive" | "multiply" | "screen";
};
type ShowPictureDslCommand = {
  kind: "showPicture";
  pictureId: number;
  image: ImageAssetReference | null;
  position: PicturePosition;
} & PictureDisplayInput;
type MovePictureDslCommand = {
  kind: "movePicture";
  pictureId: number;
  position: PicturePosition;
  duration: number;
  wait: boolean;
} & PictureDisplayInput;
type RotatePictureDslCommand = {
  kind: "rotatePicture";
  pictureId: number;
  speed: number;
};
type TintPictureDslCommand = {
  kind: "tintPicture";
  pictureId: number;
  tone: ToneInput;
  duration: number;
  wait: boolean;
};
type ErasePictureDslCommand = {
  kind: "erasePicture";
  pictureId: number;
};
type WeatherEffectType = "none" | "rain" | "storm" | "snow";
type SetWeatherEffectDslCommand = {
  kind: "setWeatherEffect";
  weather: WeatherEffectType;
  power: number;
  duration: number;
  wait: boolean;
};
type PlayBgmDslCommand = {
  kind: "playBgm";
  audio: AudioPayload<"bgm">;
};
type FadeoutBgmDslCommand = {
  kind: "fadeoutBgm";
  duration: number;
};
type SaveBgmDslCommand = {
  kind: "saveBgm";
};
type ReplayBgmDslCommand = {
  kind: "replayBgm";
};
type PlayBgsDslCommand = {
  kind: "playBgs";
  audio: AudioPayload<"bgs">;
};
type FadeoutBgsDslCommand = {
  kind: "fadeoutBgs";
  duration: number;
};
type PlayMeDslCommand = {
  kind: "playMe";
  audio: AudioPayload<"me">;
};
type PlaySeDslCommand = {
  kind: "playSe";
  audio: AudioPayload<"se">;
};
type StopSeDslCommand = {
  kind: "stopSe";
};
type PlayMovieDslCommand = {
  kind: "playMovie";
  movie: MovieAssetReference | null;
};
