//#region src/domain/references.d.ts
type ReferenceKind = "actor" | "animation" | "armor" | "class" | "commonEvent" | "enemy" | "item" | "map" | "skill" | "state" | "switch" | "tileset" | "troop" | "variable" | "weapon";
declare const audioAssetFolders: readonly ["bgm", "bgs", "me", "se"];
declare const imageAssetFolders: readonly ["animations", "battlebacks1", "battlebacks2", "characters", "enemies", "faces", "parallaxes", "pictures", "sv_actors", "sv_enemies", "system", "tilesets", "titles1", "titles2"];
type ReferenceValue<TKind extends ReferenceKind> = {
  id: number;
  kind: TKind;
} | {
  kind: TKind;
  name: string;
};
type AudioAssetFolder = (typeof audioAssetFolders)[number];
type ImageAssetFolder = (typeof imageAssetFolders)[number];
type AudioAssetReference<Folder extends AudioAssetFolder = AudioAssetFolder> = {
  kind: "asset";
  category: "audio";
  folder: Folder;
  name: string;
};
type ImageAssetReference = {
  kind: "asset";
  category: "image";
  folder: ImageAssetFolder;
  name: string;
};
type MovieAssetReference = {
  kind: "asset";
  category: "movie";
  folder: "movies";
  name: string;
};
type AssetReference = AudioAssetReference | ImageAssetReference | MovieAssetReference;
type RuntimeSelector<TScope extends string = string, TTarget extends string = string> = {
  kind: "runtimeSelector";
  scope: TScope;
  target: TTarget;
};
type ScriptInput = {
  kind: "scriptInput";
  code: string;
};
type ReferenceRange<TKind extends ReferenceKind> = {
  kind: "referenceRange";
  from: ReferenceValue<TKind>;
  to: ReferenceValue<TKind>;
};
type NumericRange = {
  kind: "numericRange";
  from: number;
  to: number;
};
type ConstantOperand = {
  kind: "constant";
  value: number;
};
type VariableOperand = {
  kind: "variable";
  variable: ReferenceValue<"variable">;
};
type RandomOperand = {
  kind: "random";
  from: number;
  to: number;
};
type ScriptOperand = {
  kind: "script";
  script: ScriptInput;
};
type ControlVariablesGameDataOperand = {
  kind: "gameData";
  source: "item";
  item: ReferenceValue<"item">;
} | {
  kind: "gameData";
  source: "weapon";
  weapon: ReferenceValue<"weapon">;
} | {
  kind: "gameData";
  source: "armor";
  armor: ReferenceValue<"armor">;
} | {
  kind: "gameData";
  source: "actor";
  actor: ReferenceValue<"actor">;
  value: "level" | "exp" | "hp" | "mp" | "mhp" | "mmp" | "atk" | "def" | "mat" | "mdf" | "agi" | "luk";
} | {
  kind: "gameData";
  source: "enemy";
  enemy: RuntimeSelector<"enemy", "enemy"> & {
    index: number;
  };
  value: "hp" | "mp" | "mhp" | "mmp" | "atk" | "def" | "mat" | "mdf" | "agi" | "luk";
} | {
  kind: "gameData";
  source: "character";
