    index: number;
  };
} | {
  kind: "gameData";
  source: "other";
  value: "mapId" | "partyMembers" | "gold" | "steps" | "playTime" | "timer" | "saveCount" | "battleCount" | "winCount" | "escapeCount";
};
type CommandOperand = ConstantOperand | VariableOperand | RandomOperand | ControlVariablesGameDataOperand | ScriptOperand;
type OperateValueOperand = number | ReferenceValue<"variable">;
type OperateValueInput = {
  operation: "increase" | "decrease";
  operand: OperateValueOperand;
};
